// Snow cover (satellite) and estimated snow depth layers, generated by the pipeline on MODEL_GRID.

import type * as maplibregl from 'maplibre-gl';
import { cellAt, gridCorners } from '../../shared/grid.ts';
import { SCHEMA_VERSION, type SnowFile } from '../../shared/types.ts';
import { escapeHtml, formatAge, formatTime } from './format.ts';

const DATA = `${import.meta.env.BASE_URL}data/`;
/** Map layer per snow picture; `white` is the Sentinel-2 snow map, the others are 250 m cells. */
export const SNOW_LAYERS = { white: 'snow-white', cover: 'snow-cover', depth: 'snow-depth', confidence: 'snow-confidence' } as const;
export type SnowLayer = keyof typeof SNOW_LAYERS;
const OPACITY: Record<SnowLayer, number> = { white: 0.95, cover: 0.9, depth: 0.85, confidence: 1 };

const COVER_CLOUD = 254;
/** viewAge value for "no clear view" in the data PNG. */
const AGE_NONE = 15;
const COVER_NODATA = 255;
const CONFIDENCE = ['low', 'medium', 'high'];

/** `path` relative to data/: snow.json, or a time slider day's copy. */
export async function loadSnow(path = 'snow.json'): Promise<SnowFile> {
  const res = await fetch(`${DATA}${path}`, { cache: 'no-cache' });
  if (!res.ok) throw new Error(`${path}: HTTP ${res.status}`);
  const file = (await res.json()) as SnowFile;
  if (file.schemaVersion !== SCHEMA_VERSION) throw new Error(`${path}: unsupported schema ${file.schemaVersion}`);
  return file;
}

/**
 * The snow pictures on the map. `show` swaps them for another snow.json (the time slider) in
 * place; layers a file lacks are hidden.
 */
export class SnowLayers {
  private visible: Record<SnowLayer, boolean>;
  private present = new Set<SnowLayer>();

  /** `before`: the layer a picture goes under when it is first added. */
  constructor(
    private map: maplibregl.Map,
    private before: (key: SnowLayer) => string | undefined,
    visible: Record<SnowLayer, boolean>,
  ) {
    this.visible = { ...visible };
  }

  /** Shows `file`'s pictures; returns the layers it has. */
  show(file: SnowFile): Set<SnowLayer> {
    const base = new URL(DATA, window.location.href).href;
    // Cache-bust per pipeline run so a reload never mixes old images with new metadata.
    const version = encodeURIComponent(file.generatedAt);
    this.present = new Set();
    for (const key of Object.keys(SNOW_LAYERS) as SnowLayer[]) {
      const id = SNOW_LAYERS[key];
      const name = file.files[key];
      if (name) {
        this.present.add(key);
        const url = `${base}${name}?v=${version}`;
        const source = this.map.getSource(id) as maplibregl.ImageSource | undefined;
        if (source) source.updateImage({ url, coordinates: gridCorners(file.grid) });
        else {
          this.map.addSource(id, { type: 'image', url, coordinates: gridCorners(file.grid) });
          this.map.addLayer(
            {
              id,
              type: 'raster',
              source: id,
              layout: { visibility: 'none' },
              paint: { 'raster-opacity': OPACITY[key], 'raster-fade-duration': 0, 'raster-resampling': 'linear' },
            },
            this.before(key),
          );
        }
      }
      this.apply(key);
    }
    return this.present;
  }

  setVisible(key: SnowLayer, on: boolean) {
    this.visible[key] = on;
    this.apply(key);
  }

  private apply(key: SnowLayer) {
    const id = SNOW_LAYERS[key];
    if (this.map.getLayer(id)) this.map.setLayoutProperty(id, 'visibility', this.visible[key] && this.present.has(key) ? 'visible' : 'none');
  }
}

/** Reads the lossless data PNG once so a click can show the estimate under the cursor. */
export class SnowValues {
  private constructor(
    private file: SnowFile,
    private pixels: Uint8ClampedArray,
  ) {}

  static async load(file: SnowFile): Promise<SnowValues | null> {
    if (!file.files.data) return null;
    const res = await fetch(`${DATA}${file.files.data}?v=${encodeURIComponent(file.generatedAt)}`);
    if (!res.ok) return null;
    const bitmap = await createImageBitmap(await res.blob(), { premultiplyAlpha: 'none', colorSpaceConversion: 'none' });
    const canvas = new OffscreenCanvas(bitmap.width, bitmap.height);
    const ctx = canvas.getContext('2d', { willReadFrequently: true })!;
    ctx.drawImage(bitmap, 0, 0);
    return new SnowValues(file, ctx.getImageData(0, 0, bitmap.width, bitmap.height).data);
  }

  /** Decodes pipeline/src/snow/render.ts dataRgba: R = age·16 + confidence·4 + depth>>8, G = depth&255, B = cover. */
  at(lon: number, lat: number): { depthCm: number; confidence: string; cover: number; viewAge: number } | null {
    const c = cellAt(this.file.grid, lon, lat);
    if (!c) return null;
    const i = (c.row * this.file.grid.width + c.col) * 4;
    const [r, g, b] = [this.pixels[i], this.pixels[i + 1], this.pixels[i + 2]];
    return { depthCm: ((r & 3) << 8) + g, confidence: CONFIDENCE[(r >> 2) & 3] ?? 'low', cover: b, viewAge: r >> 4 };
  }
}

export function coverText(cover: number): string {
  if (cover === COVER_CLOUD) return 'no clear view (cloud)';
  if (cover === COVER_NODATA) return 'no data';
  return `${cover} % snow`;
}

/** Days between the newest and the oldest of the given YYYY-MM-DD dates. */
function dayGap(days: string[]): number {
  if (days.length < 2) return 0;
  return Math.round((Date.parse(days[0]) - Date.parse(days[days.length - 1])) / 86_400_000);
}

/** Date `daysBefore` the given YYYY-MM-DD, formatted like "19 Oct". */
function dayBefore(date: string, daysBefore: number): string {
  const d = new Date(`${date}T12:00:00Z`);
  d.setUTCDate(d.getUTCDate() - daysBefore);
  return d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' });
}

/** HTML for the click panel: the estimate and the satellite view at this point. */
export function pointSnowHtml(file: SnowFile, v: ReturnType<SnowValues['at']>): string {
  if (!v || !file.depth) return '';
  let cover = 'no satellite data';
  if (file.cover.available) {
    cover =
      v.cover <= 100 && v.viewAge !== AGE_NONE
        ? `${coverText(v.cover)} of this 250 m cell (${file.cover.sensor}, ${dayBefore(file.cover.date, v.viewAge)})`
        : coverText(v.cover);
  }
  return `
    <dl class="kv">
      <dt>Estimated snow</dt><dd><strong>${v.depthCm < 1 ? 'none' : `~${v.depthCm} cm`}</strong> (confidence ${v.confidence})</dd>
      <dt>Snow cover</dt><dd>${escapeHtml(cover)}</dd>
    </dl>`;
}

/** A cell counts as snow-covered along a route from this share of snow. */
const ROUTE_SNOW_COVER = 50;

export interface RouteSnow {
  /** Shares of the sampled points: in snow-covered cells, and with no clear view. */
  snow: number;
  unseen: number;
  /** Lowest sampled elevation in a snow-covered cell, metres. */
  lowestSnowM: number | null;
  maxDepthCm: number;
}

/** Snow along a route sampled at evenly spaced [lon, lat, ele] points; null outside the grid. */
export function routeSnow(values: Pick<SnowValues, 'at'>, points: readonly number[][]): RouteSnow | null {
  let n = 0;
  let snow = 0;
  let unseen = 0;
  let lowestSnowM: number | null = null;
  let maxDepthCm = 0;
  for (const [lon, lat, ele] of points) {
    const v = values.at(lon, lat);
    if (!v) continue;
    n++;
    maxDepthCm = Math.max(maxDepthCm, v.depthCm);
    if (v.cover > 100 || v.viewAge === AGE_NONE) unseen++;
    else if (v.cover >= ROUTE_SNOW_COVER) {
      snow++;
      if (ele !== undefined) lowestSnowM = Math.min(lowestSnowM ?? Infinity, ele);
    }
  }
  return n ? { snow: snow / n, unseen: unseen / n, lowestSnowM, maxDepthCm } : null;
}

/** HTML for a via ferrata's panel: how much of it lies in snow seen from space. */
export function routeSnowHtml(file: SnowFile, s: RouteSnow | null): string {
  if (!s || !file.cover.available) return '';
  const pct = (x: number) => `${Math.round(x * 100)} %`;
  const seen =
    s.snow === 0
      ? 'no snow-covered cells along the route'
      : `about ${pct(s.snow)} of the route in snow-covered cells` +
        (s.lowestSnowM === null ? '' : `, from about ${Math.round(s.lowestSnowM / 50) * 50} m`);
  const hidden = s.unseen >= 0.05 ? `; ${pct(s.unseen)} not seen clearly (cloud)` : '';
  const depth = file.depth && s.maxDepthCm >= 1 ? `<dt>Estimated snow</dt><dd>up to ~${s.maxDepthCm} cm along the route</dd>` : '';
  return `
    <dl class="kv">
      <dt>Snow on the route</dt><dd>${escapeHtml(seen + hidden)} <span class="muted">(${escapeHtml(file.cover.sensor)}, ${escapeHtml(shortDay(file.cover.date))}, 250 m cells)</span></dd>
      ${depth}
    </dl>
    <p class="muted">Snow seen from space is summed into 250 m cells: a snowy gully or ice on shaded rock can hide in a cell counted bare, and new snow since the pass is missing.</p>`;
}

const shortDay = (date: string) => dayBefore(date, 0);

/** Info section for the layers panel and the sources dialog. */
export function snowInfoHtml(file: SnowFile): string {
  const parts: string[] = [];
  if (file.cover.available) {
    const c = file.cover;
    const total = c.stats.snow + c.stats.bare + c.stats.olderView + c.stats.cloud;
    const days = [...new Set(c.composite.map((p) => p.date))];
    const s2 = c.sensor === 'Sentinel-2';
    const share = c.shares ?? { newest: (c.stats.snow + c.stats.bare) / (total || 1), older: c.stats.olderView / (total || 1), never: c.stats.cloud / (total || 1) };
    parts.push(
      `<p><strong>Snow seen from space</strong>: ${s2 ? 'Sentinel-2, about 60 m pixels' : 'VIIRS and MODIS, 500 m'}, newest pass ${escapeHtml(c.date)}. ` +
        `${Math.round(share.newest * 100)} % of the area seen clear that day, ${Math.round(share.older * 100)} % taken from the ` +
        `${days.length - 1} passes before (up to ${dayGap(days)} days older, drawn fainter), ${Math.round(share.never * 100)} % hidden by clouds on every pass` +
        `${s2 ? ' (shown without snow, so check the date before trusting a bare patch)' : ' (hatched on the cell layer)'}.` +
        (c.snowLineM !== null ? ` Snow line about <strong>${c.snowLineM.toLocaleString('en-GB')} m</strong>.` : '') +
        `</p>`,
    );
  } else {
    parts.push(`<p><strong>Snow cover</strong>: not available (${escapeHtml(file.cover.reason)}).</p>`);
  }
  const d = file.depth;
  if (d) {
    const mae = d.validation.maeCm[d.method];
    const bands = d.validation.byBand
      .filter((b) => b.n > 0)
      .map((b) => `${escapeHtml(b.label)}: ±${b.maeCm.toFixed(1)} cm (${b.n})`)
      .join(', ');
    parts.push(
      `<p><strong>Estimated snow depth</strong> from ${d.stationCount} stations (readings up to ${formatTime(d.stationsObservedAt)}),` +
        ` ${d.method === 'trend' ? 'elevation trend' : 'elevation trend plus local corrections'}` +
        `${file.cover.available ? ', set to zero wherever the satellite saw bare ground in the last few days' : ', <strong>not checked against the satellite</strong> (no snow map), so it may show snow where there is none'}.` +
        ` Typical error when a station is hidden and predicted from the others: <strong>±${mae.toFixed(1)} cm</strong> (${bands}).` +
        ` Stations sit between ${d.stationElevationRange[0]} and ${d.stationElevationRange[1]} m; outside that range the map extrapolates.</p>`,
    );
  }
  parts.push(`<p class="muted">Generated ${formatTime(file.generatedAt)} (${formatAge(file.generatedAt)}). This is an estimate, not a measurement.</p>`);
  return parts.join('');
}
